import test from 'node:test';
import assert from 'node:assert/strict';
import { createGrid, nextGeneration, toggleCell, randomGrid } from './engine.js';

const alive = grid => grid.flatMap((row, y) => row.flatMap((cell, x) => cell ? [[x, y]] : []));

test('creates and validates grids', () => {
  assert.deepEqual(createGrid(3, 2, [[0, 0], [2, 1]]), [[true, false, false], [false, false, true]]);
  for (const dims of [[0, 2], [2, -1], [1.5, 2]]) assert.throws(() => createGrid(...dims), /width|height|dimension|integer/i);
});

test('blinker oscillates and input stays untouched', () => {
  const input = createGrid(5, 5, [[2, 1], [2, 2], [2, 3]]), snapshot = structuredClone(input);
  const output = nextGeneration(input);
  assert.deepEqual(input, snapshot);
  assert.deepEqual(alive(output), [[1, 2], [2, 2], [3, 2]]);
  assert.deepEqual(alive(nextGeneration(output)), [[2, 1], [2, 2], [2, 3]]);
});

test('edges are finite rather than wrapping', () => {
  const input = createGrid(5, 5, [[0, 1], [0, 2], [0, 3]]);
  assert.deepEqual(alive(nextGeneration(input)), [[0, 2], [1, 2]]);
});

test('toggle is immutable and rejects invalid coordinates', () => {
  const input = createGrid(2, 2), output = toggleCell(input, 1, 0);
  assert.equal(input[0][1], false); assert.equal(output[0][1], true);
  assert.equal(toggleCell(output, 1, 0)[0][1], false);
  assert.throws(() => toggleCell(input, 2, 0), /bound|coordinate/i);
});

test('random grid uses the supplied source once per cell', () => {
  const values = [.1, .9, .2, .8]; let calls = 0;
  const grid = randomGrid(2, 2, .5, () => values[calls++]);
  assert.equal(calls, 4); assert.deepEqual(grid, [[true, false], [true, false]]);
  assert.throws(() => randomGrid(2, 2, 2), /probability/i);
});
